import { useState, useRef, useEffect } from "react";

const FRAME_SRC = "data:image/png;base64,";
const BURN_SRC="data:image/png;base64,";
const INK_SRC="data:image/png;base64,";
const BG_SRC = "data:image/jpeg;base64,";
const FW=130,FH=130,OV_CY=3,OV_RX=40,OV_RY=48,NAME_Y=FH/2+18;
let _id=1;
const uid=()=>`i${_id++}`;
const mkChar=(x=200,y=200)=>({id:uid(),name:"",kana:"",birth:"",death:"",desc:"",img:null,muggle:false,deceased:false,disinherited:false,imgX:0,imgY:0,imgScale:1,burnX:0,burnY:-7,burnScale:0.45,disStyle:"burn",x,y});
const LC="#92400e";

function getMidPos(mid,chars){
  const a=chars.find(c=>c.id===mid.fromId),b=chars.find(c=>c.id===mid.toId);
  if(!a||!b)return{x:0,y:0};
  return{x:(a.x+b.x)/2,y:(a.y+OV_CY+b.y+OV_CY)/2};
}

function OrthoLines({rels,chars,mids,selLine,onCk}){
  const gp=id=>{
    const c=chars.find(c=>c.id===id);if(c)return{x:c.x,y:c.y+OV_CY,isChar:true,isMid:false};
    const m=mids.find(m=>m.id===id);if(m){const p=getMidPos(m,chars);return{x:p.x,y:p.y,isChar:false,isMid:true};}
    return null;
  };
  return(
    <g>
      {rels.map(r=>{
        const a=gp(r.from),b=gp(r.to);if(!a||!b)return null;
        const hilite=selLine===r.id;
        const clr=hilite?"#fbbf24":LC;
        let pathD;
        if(a.isMid&&b.isChar){const my=a.y+(b.y-a.y)*0.5;pathD=`M${a.x},${a.y} L${a.x},${my} L${b.x},${my} L${b.x},${b.y}`;}
        else if(b.isMid&&a.isChar){const my=b.y+(a.y-b.y)*0.5;pathD=`M${b.x},${b.y} L${b.x},${my} L${a.x},${my} L${a.x},${a.y}`;}
        else{const dx=b.x-a.x,dy=b.y-a.y,len=Math.sqrt(dx*dx+dy*dy)||1;const OA=a.isChar?54:0,OB=b.isChar?54:0;pathD=`M${a.x+dx/len*OA},${a.y+dy/len*OA} L${b.x-dx/len*OB},${b.y-dy/len*OB}`;}
        const segs=pathD.split(/[ML]/).filter(Boolean).map(s=>s.trim().split(",").map(Number));
        const mx=(segs[0][0]+segs[segs.length-1][0])/2,my2=(segs[0][1]+segs[segs.length-1][1])/2;
        return(
          <g key={r.id}>
            <path d={pathD} stroke={clr} strokeWidth={hilite?3:1.8} fill="none" opacity={0.85} style={{pointerEvents:"none"}}/>
            <path d={pathD} stroke="transparent" strokeWidth={28} fill="none" style={{cursor:"pointer",pointerEvents:"stroke"}}/>
          </g>
        );
      })}
    </g>
  );
}

function MidDot({m,chars,active,onConn}){
  const{x,y}=getMidPos(m,chars);
  const cpd=useRef(null);
  return(
    <g transform={`translate(${x},${y})`} style={{pointerEvents:"none"}}>
      <circle r={5} fill="#92400e" stroke="#451a03" strokeWidth={1} style={{pointerEvents:"none"}}/>
      <circle r={2.5} fill="#d97706" style={{pointerEvents:"none"}}/>
      <g transform="translate(12,-12)" style={{cursor:"pointer",pointerEvents:"all"}}
        onPointerDown={e=>{e.stopPropagation();cpd.current={sx:e.clientX,sy:e.clientY};}}
        onPointerUp={e=>{e.stopPropagation();if(cpd.current&&Math.hypot(e.clientX-cpd.current.sx,e.clientY-cpd.current.sy)<8)onConn(m.id);}}>
        <circle r={9} fill={active?"#f59e0b":"#78350f"}/>
        <text y={3} textAnchor="middle" fontSize={10} fill="white" style={{pointerEvents:"none",userSelect:"none"}}>⟷</text>
      </g>
    </g>
  );
}

function CharNode({ch,sel,active,onEdit,onConn}){
  const gf="none";
  const ds=[ch.birth,ch.deceased&&ch.death?`† ${ch.death}`:""].filter(Boolean).join(" — ");
  const cpd=useRef(null);
  const cpId=`cp_${ch.id}`;
  return(
    <g transform={`translate(${ch.x},${ch.y})`}>
      <defs>
        <clipPath id={cpId}><ellipse cx={0} cy={OV_CY} rx={OV_RX} ry={OV_RY}/></clipPath>
      </defs>
      <ellipse cx={0} cy={OV_CY} rx={OV_RX} ry={OV_RY} fill={ch.deceased?"#6b7280":"#d4b896"} opacity={0.6} style={{pointerEvents:"none"}}/>
      {ch.img&&<image href={ch.img}
        x={-OV_RX+(ch.imgX||0)} y={OV_CY-OV_RY+(ch.imgY||0)}
        width={OV_RX*2*(ch.imgScale||1)} height={OV_RY*2*(ch.imgScale||1)}
        clipPath={`url(#${cpId})`} preserveAspectRatio="xMidYMid slice" style={{filter:gf,pointerEvents:"none"}}/>}
      {!ch.img&&<text x={0} y={OV_CY+12} textAnchor="middle" fontSize={28} opacity={0.28} style={{pointerEvents:"none"}}>👤</text>}
      {ch.deceased&&<ellipse cx={0} cy={OV_CY} rx={OV_RX} ry={OV_RY} fill="#111827" opacity={0.4} style={{pointerEvents:"none"}}/>}
      <image href={FRAME_SRC} x={-FW/2} y={-FH/2} width={FW} height={FH} style={{filter:gf,pointerEvents:"none"}}/>
      {ch.disinherited&&(
        <image href={ch.disStyle==="ink"?INK_SRC:BURN_SRC}
          x={-(FW/2)*(ch.burnScale||1)+(ch.burnX||0)}
          y={-(FH/2)*(ch.burnScale||1)+(ch.burnY||0)}
          width={FW*(ch.burnScale||1)} height={FH*(ch.burnScale||1)}
          style={{pointerEvents:"none"}} preserveAspectRatio="xMidYMid meet"/>
      )}
      {sel&&<ellipse cx={0} cy={OV_CY} rx={OV_RX+9} ry={OV_RY+9} fill="none" stroke="#fbbf24" strokeWidth={3} style={{pointerEvents:"none"}}/>}
      {ch.muggle&&<g style={{pointerEvents:"none"}}>
      <rect x={-20} y={-FH/2-8} width={40} height={14} rx={3} fill="#374151"/>
      <text x={0} y={-FH/2+2} textAnchor="middle" fontSize={8} fill="#d1d5db" fontFamily="serif" fontWeight="700">Muggle</text>     </g>}
     <text y={NAME_Y} textAnchor="middle" fontSize={12} fill={ch.deceased?"#9ca3af":"#1c0e04"} fontFamily="serif" fontWeight="700" style={{pointerEvents:"none"}}>{ch.name||"（未設定）"}</text>      {ch.kana&&<text y={NAME_Y+14} textAnchor="middle" fontSize={9} fill="#78716c" fontFamily="serif" style={{pointerEvents:"none"}}>{ch.kana}</text>}
      {ds&&<text y={NAME_Y+(ch.kana?28:14)} textAnchor="middle" fontSize={9} fill="#a16207" fontFamily="serif" style={{pointerEvents:"none"}}>{ds}</text>}
      {/* Tap zone — used only for opening edit, drag handled by parent */}
      <ellipse cx={0} cy={OV_CY} rx={OV_RX+4} ry={OV_RY+4} fill="transparent" style={{cursor:"grab"}}/>
      {/* ⟷ btn */}
      <g transform={`translate(${FW/2-2},${-FH/2+10})`} style={{cursor:"pointer"}}
        onPointerDown={e=>{e.stopPropagation();cpd.current={sx:e.clientX,sy:e.clientY};}}
        onPointerUp={e=>{e.stopPropagation();if(cpd.current&&Math.hypot(e.clientX-cpd.current.sx,e.clientY-cpd.current.sy)<8)onConn(ch.id);}}>
        <circle r={14} fill={active?"#f59e0b":"#92400e"} stroke="#451a03" strokeWidth={1.5}/>
        <text y={5} textAnchor="middle" fontSize={16} fill="white" style={{pointerEvents:"none",userSelect:"none"}}>⟷</text>
      </g>
    </g>
  );
}

function App() {
  const [chars,setChars]=useState([]);
  const [rels,setRels]=useState([]);
  const [mids,setMids]=useState([]);
  const [selLine,setSelLine]=useState(null);
  const [selNode,setSelNode]=useState(null);
  const [editId,setEditId]=useState(null);
  const [ed,setEd]=useState(null);
  const [familyCrest,setFamilyCrest]=useState(null);
  const [familyMotto,setFamilyMotto]=useState("");
  const [familyTitle,setFamilyTitle]=useState("");
  const connRef=useRef({from:null});
  const [connFrom,setConnFrom]=useState(null);
  const [scale,setScale]=useState(1);
  const [pan,setPan]=useState({x:0,y:0});
  const [menu,setMenu]=useState(false);
  const [bulkOpen,setBulkOpen]=useState(false);
  const [bulkText,setBulkText]=useState("");
  const [helpOpen,setHelpOpen]=useState(false);
  const [familyOpen,setFamilyOpen]=useState(false);
  const [adjustMode,setAdjustMode]=useState(null); // null|'img'|'burn'
  const [adjustTargetId,setAdjustTargetId]=useState(null);

  const scaleR=useRef(1),panR=useRef({x:0,y:0});
  const charsR=useRef([]),midsR=useRef([]),relsR=useRef([]);
  const svgRef=useRef(),fileRef=useRef(),crestRef=useRef(),importRef=useRef();

  // ── Drag/Pan state ──────────────────────────────────────
  // Single pointer state machine: null | {kind:"drag",id,ox,oy,sx,sy,moved} | {kind:"pan",sx,sy,px,py}
  const ptrRef=useRef(null);
  const pinchRef=useRef(null);

  useEffect(()=>{scaleR.current=scale;},[scale]);
  useEffect(()=>{panR.current=pan;},[pan]);
  useEffect(()=>{charsR.current=chars;},[chars]);
  useEffect(()=>{midsR.current=mids;},[mids]);
  useEffect(()=>{relsR.current=rels;},[rels]);

  const setConn=(from)=>{connRef.current={from};setConnFrom(from);};
  const clearConn=()=>{connRef.current={from:null};setConnFrom(null);};

  useEffect(()=>{try{const c=localStorage.getItem("wfcD_c"),r=localStorage.getItem("wfcD_r"),m=localStorage.getItem("wfcD_m");const fc=localStorage.getItem("wfcD_fc"),fm=localStorage.getItem("wfcD_fm"),ft=localStorage.getItem("wfcD_ft");if(c)setChars(JSON.parse(c));if(r)setRels(JSON.parse(r));if(m)setMids(JSON.parse(m));if(fc)setFamilyCrest(fc);if(fm)setFamilyMotto(fm);if(ft)setFamilyTitle(ft);}catch(_){}}, []);
  useEffect(()=>{try{localStorage.setItem("wfcD_c",JSON.stringify(chars));localStorage.setItem("wfcD_r",JSON.stringify(rels));localStorage.setItem("wfcD_m",JSON.stringify(mids));if(familyCrest)localStorage.setItem("wfcD_fc",familyCrest);localStorage.setItem("wfcD_fm",familyMotto);localStorage.setItem("wfcD_ft",familyTitle);}catch(_){}}, [chars,rels,mids,familyCrest,familyMotto,familyTitle]);

  const svgXY=(cx,cy)=>{const r=svgRef.current?.getBoundingClientRect()||{left:0,top:0};return{x:(cx-r.left)/scaleR.current-panR.current.x,y:(cy-r.top)/scaleR.current-panR.current.y};};

  // ── SVG pointer handlers ─────────────────────────────────
  // Nodes do stopPropagation on their own pointerDown → SVG only sees background taps
  // Except nodes' transparent oval does NOT stopPropagation → SVG sees it for drag
const onSvgPD=e=>{
    if(e.cancelable)e.preventDefault();
    const activePointers=(pinchRef.current?.pointers||[]).filter(p=>p.id!==e.pointerId);
    activePointers.push({id:e.pointerId,x:e.clientX,y:e.clientY});
    if(activePointers.length>=2){
      const [a,b]=activePointers;
      pinchRef.current={pointers:activePointers,dist:Math.hypot(a.x-b.x,a.y-b.y),s:scaleR.current};
      ptrRef.current=null;return;
    }
    pinchRef.current={pointers:activePointers};
    const cx=e.clientX,cy=e.clientY;
    const w=svgXY(cx,cy);
    const hit=[...charsR.current].reverse().find(c=>{
      const dx=c.x-w.x,dy=(c.y+OV_CY)-w.y;
      return dx*dx/(60*60)+dy*dy/(60*60)<=1;
    });
    if(hit){
      ptrRef.current={kind:"drag",id:hit.id,ox:w.x-hit.x,oy:w.y-hit.y,sx:cx,sy:cy,moved:false};
    } else {
      ptrRef.current={kind:"pan",sx:cx,sy:cy,px:panR.current.x,py:panR.current.y};
    }
  };

const onSvgPM=e=>{
    if(e.cancelable)e.preventDefault();
    if(pinchRef.current?.dist){
      const pointers=pinchRef.current.pointers.map(p=>p.id===e.pointerId?{id:e.pointerId,x:e.clientX,y:e.clientY}:p);
      pinchRef.current={...pinchRef.current,pointers};
      if(pointers.length>=2){
        const [a,b]=pointers;
        const d=Math.hypot(a.x-b.x,a.y-b.y);
        const ns=Math.min(3,Math.max(0.2,pinchRef.current.s*(d/pinchRef.current.dist)));
        setScale(ns);scaleR.current=ns;
      }
      return;
    }
    if(pinchRef.current&&!pinchRef.current.dist){
      pinchRef.current.pointers=pinchRef.current.pointers.map(p=>p.id===e.pointerId?{id:e.pointerId,x:e.clientX,y:e.clientY}:p);
    }
    const p=ptrRef.current;if(!p)return;
    const cx=e.clientX,cy=e.clientY;
    if(p.kind==="drag"){
      if(!p.moved&&Math.hypot(cx-p.sx,cy-p.sy)<6)return;
      p.moved=true;
      const w=svgXY(cx,cy);
      setChars(prev=>prev.map(c=>c.id===p.id?{...c,x:w.x-p.ox,y:w.y-p.oy}:c));
    } else if(p.kind==="pan"){
      const nx=p.px+(cx-p.sx)/scaleR.current;
      const ny=p.py+(cy-p.sy)/scaleR.current;
      setPan({x:nx,y:ny});panR.current={x:nx,y:ny};
    }
  };

  const onSvgPU=e=>{
    const p=ptrRef.current;
    const pointers=(pinchRef.current?.pointers||[]).filter(p=>p.id!==e.pointerId);
    if(pointers.length<2)pinchRef.current=pointers.length?{pointers}:null;
    else pinchRef.current={...pinchRef.current,pointers};
    ptrRef.current=null;
    if(!p)return;
    const dist=Math.hypot(e.clientX-p.sx,e.clientY-p.sy);
    if(p.kind==="drag"&&!p.moved){
      // tap on node → open edit
      const{from}=connRef.current;
      if(from&&from!==p.id){addRel(from,p.id);clearConn();return;}
      if(from===p.id){clearConn();return;}
      clearConn();
      const c=charsR.current.find(x=>x.id===p.id);
      if(c){setEd({...c});setEditId(c.id);setSelLine(null);}
    } else if(p.kind==="pan"&&dist<6){
      // 線のhit-test（SVG座標でセグメントとの距離を計算）
      const w=svgXY(p.sx,p.sy);
      const HIT_D=20; // ヒット判定距離（SVG単位）
      let hitLine=null,minD=HIT_D;
      const gpFn=id=>{
        const c=charsR.current.find(c=>c.id===id);if(c)return{x:c.x,y:c.y+OV_CY};
        const m=midsR.current.find(m=>m.id===id);if(m){const mp=getMidPos(m,charsR.current);return{x:mp.x,y:mp.y};}
        return null;
      };
      for(const r of relsR.current){
        const a=gpFn(r.from),b=gpFn(r.to);if(!a||!b)continue;
        // セグメント列を生成（OrthoLinesと同じロジック）
        const aIsMid=!!midsR.current.find(m=>m.id===r.from);
        const bIsMid=!!midsR.current.find(m=>m.id===r.to);
        let segs=[];
        if(aIsMid&&!bIsMid){const my=a.y+(b.y-a.y)*0.5;segs=[[a.x,a.y,a.x,my],[a.x,my,b.x,my],[b.x,my,b.x,b.y]];}
        else if(bIsMid&&!aIsMid){const my=b.y+(a.y-b.y)*0.5;segs=[[b.x,b.y,b.x,my],[b.x,my,a.x,my],[a.x,my,a.x,a.y]];}
        else{const dx=b.x-a.x,dy=b.y-a.y,len=Math.sqrt(dx*dx+dy*dy)||1;const OA=54,OB=54;segs=[[a.x+dx/len*OA,a.y+dy/len*OA,b.x-dx/len*OB,b.y-dy/len*OB]];}
        for(const [x1,y1,x2,y2] of segs){
          const dx=x2-x1,dy=y2-y1,len2=dx*dx+dy*dy;
          if(len2<1)continue;
          const t=Math.max(0,Math.min(1,((w.x-x1)*dx+(w.y-y1)*dy)/len2));
          const d=Math.hypot(w.x-(x1+t*dx),w.y-(y1+t*dy));
          if(d<minD){minD=d;hitLine=r.id;}
        }
      }
      if(hitLine){onLineClick(hitLine,0,0);return;}
      clearConn();setSelLine(null);setSelNode(null);
    }
  };

  useEffect(()=>{const b=e=>{if(e.cancelable)e.preventDefault();};window.addEventListener("touchmove",b,{passive:false});return()=>window.removeEventListener("touchmove",b);},[]);
  useEffect(()=>{const svg=svgRef.current;if(!svg)return;const wh=e=>{e.preventDefault();const r=svg.getBoundingClientRect(),s=scaleR.current,p=panR.current;const wx=(e.clientX-r.left)/s-p.x,wy=(e.clientY-r.top)/s-p.y;const ns=Math.min(3,Math.max(0.2,s*(1-e.deltaY*0.001)));const np={x:(e.clientX-r.left)/ns-wx,y:(e.clientY-r.top)/ns-wy};setScale(ns);setPan(np);scaleR.current=ns;panR.current=np;};svg.addEventListener("wheel",wh,{passive:false});return()=>svg.removeEventListener("wheel",wh);},[]);

  const addRel=(a,b)=>{if(!relsR.current.find(r=>(r.from===a&&r.to===b)||(r.from===b&&r.to===a)))setRels(p=>[...p,{id:uid(),from:a,to:b}]);};

  const onConn=id=>{
    const{from}=connRef.current;
    if(!from){setConn(id);return;}
    if(from===id){clearConn();return;}
    addRel(from,id);clearConn();
  };

  const onLineClick=(lineId,mx,my)=>{
    const{from}=connRef.current;
    if(from){
      const rel=relsR.current.find(r=>r.id===lineId);
      const fIsC=!!charsR.current.find(c=>c.id===rel?.from);
      const tIsC=!!charsR.current.find(c=>c.id===rel?.to);
      if(rel&&fIsC&&tIsC){
        const em=midsR.current.find(m=>m.lineId===lineId);
        if(em){addRel(em.id,from);}
        else{const nm={id:uid(),lineId,fromId:rel.from,toId:rel.to};setMids(p=>[...p,nm]);setRels(p=>[...p,{id:uid(),from:nm.id,to:from}]);}
      }
      clearConn();setSelLine(null);return;
    }
    setSelLine(s=>s===lineId?null:lineId);setSelNode(null);
  };

  const delLine=()=>{
    if(!selLine)return;
    const mid=midsR.current.find(m=>m.lineId===selLine);
    if(mid){setRels(p=>p.filter(r=>r.id!==selLine&&r.from!==mid.id&&r.to!==mid.id));setMids(p=>p.filter(m=>m.id!==mid.id));}
    else{
      setRels(p=>p.filter(r=>r.id!==selLine));
      const rel=relsR.current.find(r=>r.id===selLine);
      const midId=[rel?.from,rel?.to].find(id=>midsR.current.some(m=>m.id===id));
      if(midId){const rem=relsR.current.filter(r=>r.id!==selLine&&(r.from===midId||r.to===midId));if(rem.length===0)setMids(p=>p.filter(m=>m.id!==midId));}
    }
    setSelLine(null);
  };

  const doReset=()=>{if(!window.confirm("全データをリセットしますか？"))return;setChars([]);setRels([]);setMids([]);setFamilyCrest(null);setFamilyMotto("");setFamilyTitle("");try{["wfcD_c","wfcD_r","wfcD_m","wfcD_fc","wfcD_fm","wfcD_ft"].forEach(k=>localStorage.removeItem(k));}catch(_){}};
  const addChar=()=>{const r=svgRef.current?.getBoundingClientRect();const s=scaleR.current,p=panR.current;const cx=r?r.width/2/s-p.x:200,cy=r?r.height/2/s-p.y:200;const c=mkChar(cx+Math.random()*80-40,cy+Math.random()*80-40);setChars(prev=>[...prev,c]);setEd({...c});setEditId(c.id);};
  const saveEdit=()=>{setChars(p=>p.map(c=>c.id===ed.id?{...ed}:c));setEditId(null);};
  const delChar=id=>{const rids=relsR.current.filter(r=>r.from===id||r.to===id).map(r=>r.id);const am=midsR.current.filter(m=>m.fromId===id||m.toId===id||rids.includes(m.lineId)).map(m=>m.id);setChars(p=>p.filter(c=>c.id!==id));setRels(p=>p.filter(r=>r.from!==id&&r.to!==id&&!am.includes(r.from)&&!am.includes(r.to)));setMids(p=>p.filter(m=>!am.includes(m.id)));setEditId(null);};
  const hImg=e=>{const f=e.target.files[0];if(!f)return;const rd=new FileReader();rd.onload=ev=>{const img=ev.target.result;setEd(d=>({...d,img}));setChars(p=>p.map(c=>c.id===ed.id?{...c,img}:c));};rd.readAsDataURL(f);};
  const hCrest=e=>{const f=e.target.files[0];if(!f)return;const rd=new FileReader();rd.onload=ev=>setFamilyCrest(ev.target.result);rd.readAsDataURL(f);};
  const doBulk=()=>{const lines=bulkText.split("\n").filter(l=>l.trim());setChars(p=>[...p,...lines.map((l,i)=>{const p2=l.split(",").map(s=>s.trim());return{...mkChar(150+i*170,200+Math.random()*60),name:p2[0]||"",kana:p2[1]||"",birth:p2[2]||"",death:p2[3]||""};})]);setBulkText("");setBulkOpen(false);};
  const doExport=()=>{const a=document.createElement("a");a.download="wfc_data.json";a.href=URL.createObjectURL(new Blob([JSON.stringify({chars,rels,mids,familyCrest,familyMotto,familyTitle},null,2)],{type:"application/json"}));a.click();};
  const doImport=e=>{const f=e.target.files[0];if(!f)return;const rd=new FileReader();rd.onload=ev=>{try{const d=JSON.parse(ev.target.result);if(d.chars)setChars(d.chars);if(d.rels)setRels(d.rels);if(d.mids)setMids(d.mids);if(d.familyCrest)setFamilyCrest(d.familyCrest);if(d.familyMotto!==undefined)setFamilyMotto(d.familyMotto);if(d.familyTitle!==undefined)setFamilyTitle(d.familyTitle);}catch(_){alert("読み込みエラー");}};rd.readAsText(f);};

  const buildSVG=()=>{
    const ax=chars.map(c=>c.x),ay=chars.map(c=>c.y);
    const mnx=(ax.length?Math.min(...ax):0)-160,mny=(ay.length?Math.min(...ay):0)-160,mxx=(ax.length?Math.max(...ax):400)+200,mxy=(ay.length?Math.max(...ay):400)+240;
    const W=mxx-mnx,H=mxy-mny;
    const gp=id=>{const c=chars.find(c=>c.id===id);if(c)return{x:c.x,y:c.y+OV_CY,isChar:true,isMid:false};const m=mids.find(m=>m.id===id);if(m){const p=getMidPos(m,chars);return{x:p.x,y:p.y,isChar:false,isMid:true};}return null;};
    const ls=rels.map(r=>{const a=gp(r.from),b=gp(r.to);if(!a||!b)return"";let d;if(a.isMid&&b.isChar){const my=a.y+(b.y-a.y)*0.5;d=`M${a.x},${a.y} L${a.x},${my} L${b.x},${my} L${b.x},${b.y}`;}else if(b.isMid&&a.isChar){const my=b.y+(a.y-b.y)*0.5;d=`M${b.x},${b.y} L${b.x},${my} L${a.x},${my} L${a.x},${a.y}`;}else{const dx=b.x-a.x,dy=b.y-a.y,len=Math.sqrt(dx*dx+dy*dy)||1;const OA=a.isChar?54:0,OB=b.isChar?54:0;d=`M${a.x+dx/len*OA},${a.y+dy/len*OA} L${b.x-dx/len*OB},${b.y-dy/len*OB}`;}return`<path d="${d}" stroke="${LC}" stroke-width="1.8" fill="none" opacity="0.85"/>`;}).join("");
    const ms=mids.map(m=>{const p=getMidPos(m,chars);return`<circle cx="${p.x}" cy="${p.y}" r="5" fill="#92400e" stroke="#451a03" stroke-width="1"/><circle cx="${p.x}" cy="${p.y}" r="2.5" fill="#d97706"/>`;}).join("");
    const ns=chars.map(c=>{const gf="none";const ds=[c.birth,c.deceased&&c.death?`† ${c.death}`:""].filter(Boolean).join(" — ");const cp=`cp_${c.id}`;return`<g transform="translate(${c.x},${c.y})" data-desc="${(c.desc||"").replace(/&/g,"&amp;").replace(/"/g,"&quot;")}"><defs><clipPath id="${cp}"><ellipse cx="0" cy="${OV_CY}" rx="${OV_RX}" ry="${OV_RY}"/></clipPath></defs><ellipse cx="0" cy="${OV_CY}" rx="${OV_RX}" ry="${OV_RY}" fill="${c.deceased?"#6b7280":"#d4b896"}" opacity="0.6"/>${c.img?`<image href="${c.img}" x="${-OV_RX+(c.imgX||0)}" y="${OV_CY-OV_RY+(c.imgY||0)}" width="${OV_RX*2*(c.imgScale||1)}" height="${OV_RY*2*(c.imgScale||1)}" clip-path="url(#${cp})" preserveAspectRatio="xMidYMid slice" style="filter:${gf}"/>`:`<text x="0" y="${OV_CY+16}" text-anchor="middle" font-size="40" font-family="serif" clip-path="url(#${cp})">👤</text>`}${c.deceased?`<ellipse cx="0" cy="${OV_CY}" rx="${OV_RX}" ry="${OV_RY}" fill="#111827" opacity="0.4"/>`:""}<image href="${FRAME_SRC}" x="${-FW/2}" y="${-FH/2}" width="${FW}" height="${FH}" style="filter:${gf}"/>${c.disinherited?`<image href="${c.disStyle==="ink"?INK_SRC:BURN_SRC}" x="${-(FW/2)*(c.burnScale||1)+(c.burnX||0)}" y="${-(FH/2)*(c.burnScale||1)+(c.burnY||0)}" width="${FW*(c.burnScale||1)}" height="${FH*(c.burnScale||1)}" preserveAspectRatio="xMidYMid meet"/>`:""}${c.muggle?`<rect x="-20" y="${-FH/2-8}" width="40" height="14" rx="3" fill="#374151"/><text x="0" y="${-FH/2+2}" text-anchor="middle" font-size="8" fill="#d1d5db" font-family="serif" font-weight="700">Muggle</text>`:""}<text y="${NAME_Y}" text-anchor="middle" font-size="12" fill="${c.deceased?"#9ca3af":"#1c0e04"}" font-family="serif" font-weight="700">${(c.name||"（未設定）").replace(/&/g,"&amp;")}</text>${c.kana?`<text y="${NAME_Y+14}" text-anchor="middle" font-size="9" fill="#78716c" font-family="serif">${c.kana.replace(/&/g,"&amp;")}</text>`:""}${ds?`<text y="${NAME_Y+(c.kana?28:14)}" text-anchor="middle" font-size="9" fill="#a16207" font-family="serif">${ds}</text>`:""}</g>`;}).join("");
    // タイトル領域（上部）
    const TH=familyTitle?70:0;
    const titleSVG=familyTitle?`<text x="${mnx+W/2}" y="${mny+44}" text-anchor="middle" font-size="52" fill="#5c3210" font-family="'Cinzel','Palatino Linotype',serif" font-weight="700" letter-spacing="8" opacity="0.95">${familyTitle.replace(/&/g,"&amp;")}</text><line x1="${mnx+W/2-160}" y1="${mny+56}" x2="${mnx+W/2-18}" y2="${mny+56}" stroke="#92400e" stroke-width="1" opacity="0.7"/><polygon points="${mnx+W/2},${mny+50} ${mnx+W/2+8},${mny+56} ${mnx+W/2},${mny+62} ${mnx+W/2-8},${mny+56}" fill="#92400e" opacity="0.8"/><line x1="${mnx+W/2+18}" y1="${mny+56}" x2="${mnx+W/2+160}" y2="${mny+56}" stroke="#92400e" stroke-width="1" opacity="0.7"/>`:"";
    // 家紋・家訓領域（下部中央）
const hasCrest=!!familyCrest,hasMotto=!!familyMotto;
    const crestSize=160;
    const BH=hasCrest&&hasMotto?320:hasCrest?200:hasMotto?100:0;
    const bottomY=mny+H+TH;
    const crestSVG=hasCrest?`<image href="${familyCrest}" x="${mnx+W/2-crestSize/2}" y="${bottomY+20}" width="${crestSize}" height="${crestSize}" preserveAspectRatio="xMidYMid meet"/>`:"";
    const mottoY=hasCrest?bottomY+20+crestSize+8:bottomY+50;    const mottoSVG=hasMotto?`<text x="${mnx+W/2}" y="${mottoY}" text-anchor="middle" font-size="16" fill="#1c0e04" font-family="'Cinzel','Palatino Linotype',serif" font-weight="700" letter-spacing="3">${familyMotto.replace(/&/g,"&amp;")}</text>`:"";
    const totalH=H+TH+BH;
    const viewY=mny-TH;
    const bgRect=`<image href="${BG_SRC}" x="${mnx}" y="${viewY}" width="${W}" height="${totalH}" preserveAspectRatio="xMidYMid slice"/>`;
    return{s:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${mnx} ${viewY} ${W} ${totalH}" width="${W}" height="${totalH}">${bgRect}<defs/>${titleSVG}${ls}${ms}${ns}${crestSVG}${mottoSVG}</svg>`,W,H:totalH,mnx,mny:viewY};
  };

  const doHTML=()=>{
    const{s}=buildSVG();
    const html=`<!DOCTYPE html><html lang="ja"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${familyTitle||"Wizard Family Chronicle"}</title><style>*{margin:0;padding:0;box-sizing:border-box;}html,body{width:100%;height:100%;background:#f5edd8;font-family:serif;}#wrap{width:100vw;height:100vh;display:flex;align-items:center;justify-content:center;overflow:hidden;}svg{max-width:100%;max-height:100%;}.tt{position:fixed;background:rgba(18,6,0,.92);color:#fef3c7;padding:8px 12px;border-radius:8px;font-size:12px;max-width:220px;pointer-events:none;display:none;border:1px solid #92400e;z-index:10;}</style></head><body><div id="wrap">${s}</div><div class="tt" id="tt"></div><script>document.querySelectorAll("[data-desc]").forEach(el=>{const tt=document.getElementById("tt"),d=el.getAttribute("data-desc");if(!d)return;el.addEventListener("mouseenter",()=>{tt.textContent=d;tt.style.display="block";});el.addEventListener("mousemove",e=>{tt.style.left=(e.clientX+14)+"px";tt.style.top=(e.clientY+14)+"px";});el.addEventListener("mouseleave",()=>{tt.style.display="none";});});<\/script></body></html>`;
    const a=document.createElement("a");a.download="family-chronicle.html";a.href=URL.createObjectURL(new Blob([html],{type:"text/html"}));a.click();
  };
  const doImg=type=>{
    const{s,W,H}=buildSVG();
    const SC=type==="png"?2:1;
    const svgBlob=new Blob([s],{type:"image/svg+xml;charset=utf-8"});
    const svgUrl=URL.createObjectURL(svgBlob);
    const cv=document.createElement("canvas");
    cv.width=W*SC;cv.height=H*SC;
    const ctx=cv.getContext("2d");
    ctx.scale(SC,SC);
    ctx.fillStyle="#f5edd8";
    ctx.fillRect(0,0,W,H);
    const img=new Image();
    img.onload=()=>{
      ctx.drawImage(img,0,0,W,H);
      const a=document.createElement("a");
      a.download=`family-chronicle.${type==="jpeg"?"jpg":"png"}`;
      a.href=cv.toDataURL(type==="jpeg"?"image/jpeg":"image/png",type==="jpeg"?0.92:undefined);
      a.click();
    };
    img.onerror=()=>alert("PNG保存に失敗しました。");
    img.src=svgUrl;
  };

  const IS={width:"100%",background:"#0f0601",border:"1px solid #78350f",color:"#fef3c7",padding:"8px",borderRadius:4,fontSize:13,fontFamily:"serif",boxSizing:"border-box"};
  const MB={width:"100%",background:"#1a0800",color:"#fef3c7",border:"1px solid #78350f",padding:"11px 14px",borderRadius:6,cursor:"pointer",fontFamily:"serif",fontSize:13,textAlign:"left",display:"flex",alignItems:"center",gap:10,marginBottom:6};
  const MBD={...MB,color:"#ef4444",border:"1px solid #7f1d1d"};

  return(
    <div style={{fontFamily:"serif",height:"100dvh",display:"flex",flexDirection:"column",overflow:"hidden",touchAction:"none",WebkitUserSelect:"none",userSelect:"none",overscrollBehavior:"none"}}>
      <style>{`html,body{overscroll-behavior:none;overflow:hidden;touch-action:none;margin:0;}`}</style>
      <header style={{background:"linear-gradient(135deg,#1c0800,#3b1a08 50%,#1c0800)",borderBottom:"2px solid #78350f",padding:"8px 12px",display:"flex",alignItems:"center",gap:8,flexShrink:0}}>
        <button onClick={()=>setMenu(true)} style={{background:"none",border:"none",color:"#fbbf24",fontSize:22,cursor:"pointer",padding:"0 4px"}}>☰</button>
        <span style={{flex:1,fontSize:14,color:"#fbbf24",letterSpacing:"0.05em",whiteSpace:"nowrap",fontFamily:"serif",fontWeight:"700"}}>ウィザワ向け家系図メーカー</span>
<button onClick={()=>setFamilyOpen(true)} style={{background:"#3b1a08",color:"#fbbf24",border:"1px solid #92400e",padding:"5px 10px",borderRadius:4,cursor:"pointer",fontFamily:"serif",fontSize:12,flexShrink:0}}>設定</button>
        <button onClick={addChar} style={{background:"#92400e",color:"#fef3c7",border:"none",padding:"7px 12px",borderRadius:4,cursor:"pointer",fontFamily:"serif",fontSize:12}}>＋ 追加</button>
        {[["＋",()=>{const ns=Math.min(3,scaleR.current+0.25);setScale(ns);scaleR.current=ns;}],["－",()=>{const ns=Math.max(0.2,scaleR.current-0.25);setScale(ns);scaleR.current=ns;}],["⟳",()=>{setScale(1);setPan({x:0,y:0});scaleR.current=1;panR.current={x:0,y:0};}]].map(([l,fn])=>(
          <button key={l} onClick={fn} style={{background:"#2d1206",color:"#fbbf24",border:"1px solid #78350f",width:28,height:28,borderRadius:4,cursor:"pointer",fontSize:14,flexShrink:0}}>{l}</button>
        ))}
      </header>
      <div style={{flex:1,position:"relative",overflow:"hidden",touchAction:"none"}}>
        {selLine&&!connFrom&&(<div style={{position:"absolute",top:10,left:"50%",transform:"translateX(-50%)",background:"#1c0800",border:"1px solid #92400e",color:"#fef3c7",padding:"6px 14px",borderRadius:20,fontSize:12,zIndex:10,display:"flex",alignItems:"center",gap:12,boxShadow:"0 2px 12px rgba(0,0,0,.5)"}}>
          <span>線を選択中</span>
          <button onClick={delLine} style={{background:"#7f1d1d",color:"white",border:"none",padding:"4px 10px",borderRadius:6,cursor:"pointer",fontSize:12}}>🗑 削除</button>
          <button onClick={()=>setSelLine(null)} style={{background:"none",color:"#92400e",border:"none",fontSize:16,cursor:"pointer"}}>✕</button>
        </div>)}
        {connFrom&&(<div style={{position:"absolute",top:10,left:"50%",transform:"translateX(-50%)",background:"#1a3a5c",border:"1px solid #3b82f6",color:"#bfdbfe",padding:"6px 16px",borderRadius:20,fontSize:12,zIndex:10,display:"flex",alignItems:"center",gap:10,whiteSpace:"nowrap",boxShadow:"0 2px 12px rgba(0,0,0,.5)"}}>
          <span>接続先をタップ、または線をタップで●作成</span>
          <button onClick={clearConn} style={{background:"none",border:"none",color:"inherit",fontSize:15,cursor:"pointer",opacity:0.7}}>✕</button>
        </div>)}
        <svg ref={svgRef} width="100%" height="100%"
          style={{backgroundImage:`url(${BG_SRC})`,backgroundSize:"contain",backgroundRepeat:"repeat",display:"block",touchAction:"none"}}
          onPointerDown={onSvgPD} onPointerMove={onSvgPM} onPointerUp={onSvgPU} onPointerCancel={e=>{ptrRef.current=null;pinchRef.current=null;}}>
          <defs>
            

            <radialGradient id="vig" cx="50%" cy="50%" r="70%"><stop offset="55%" stopColor="transparent"/><stop offset="100%" stopColor="rgba(20,8,0,.15)"/></radialGradient>
          </defs>
          <g transform={`scale(${scale}) translate(${pan.x},${pan.y})`}>
            <OrthoLines rels={rels} chars={chars} mids={mids} selLine={selLine} onCk={onLineClick}/>
            {mids.map(m=><MidDot key={m.id} m={m} chars={chars} active={connFrom===m.id} onConn={onConn}/>)}
            {chars.map(c=><CharNode key={c.id} ch={c} sel={selNode===c.id} active={connFrom===c.id} onEdit={()=>{}} onConn={onConn}/>)}
          </g>
          {chars.length===0&&<text x="50%" y="50%" textAnchor="middle" fontSize={15} fill="#78350f" fontFamily="serif" opacity={0.7} style={{pointerEvents:"none"}}>＋ 追加 でキャラクターを登録</text>}
          <rect width="100%" height="100%" fill="url(#vig)" style={{pointerEvents:"none"}}/>
        </svg>
      </div>
      {menu&&(<><div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.5)",zIndex:300}} onClick={()=>setMenu(false)}/><div style={{position:"fixed",top:0,right:0,bottom:0,width:260,background:"linear-gradient(180deg,#2d1206,#180900)",borderLeft:"2px solid #78350f",zIndex:301,overflowY:"auto",padding:"16px 14px"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}><span style={{color:"#fbbf24",fontSize:14,fontWeight:"700"}}>メニュー</span><button onClick={()=>setMenu(false)} style={{background:"none",border:"none",color:"#92400e",fontSize:20,cursor:"pointer"}}>✕</button></div>
        <div style={{color:"#a16207",fontSize:10,marginBottom:6}}>一気追加</div><p style={{color:"#d1a054",fontSize:10,margin:"0 0 8px"}}>CSVで複数キャラを一括入力できます</p>
        <button style={MB} onClick={()=>{setBulkOpen(true);setMenu(false);}}>📋 テキストで一括入力</button>
        <div style={{color:"#a16207",fontSize:10,marginTop:14,marginBottom:6}}>途中保存</div><p style={{color:"#d1a054",fontSize:10,margin:"0 0 8px"}}>データはブラウザに自動保存されます。</p>
        <button style={MB} onClick={doExport}>💾 データをエクスポート</button>
        <button style={MB} onClick={()=>importRef.current?.click()}>📂 データをインポート</button>
        <input ref={importRef} type="file" accept=".json" style={{display:"none"}} onChange={doImport}/>
        <button style={MBD} onClick={doReset}>⚠ データをリセット（全て）</button>
        <div style={{color:"#a16207",fontSize:10,marginTop:14,marginBottom:6}}>家紋・家訓・タイトル</div>
        <button style={MB} onClick={()=>{setFamilyOpen(true);setMenu(false);}}>⚜ 家紋・家訓・タイトルを設定</button>
        <div style={{color:"#a16207",fontSize:10,marginTop:14,marginBottom:6}}>保存・共有</div>
        <button style={MB} onClick={()=>{doHTML();setMenu(false);}}>🌐 HTMLで保存</button>
        <button style={MB} onClick={()=>{doImg("png");setMenu(false);}}>🖼 PNG保存（高画質）</button>
        <button style={MB} onClick={()=>{doImg("jpeg");setMenu(false);}}>📸 JPEG保存（投稿向け）</button>
        <div style={{color:"#a16207",fontSize:10,marginTop:14,marginBottom:6}}>ヘルプ</div>
        <button style={MB} onClick={()=>{setHelpOpen(true);setMenu(false);}}>❓ 使い方</button>
      </div></>)}
      {familyOpen&&(<><div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.6)",zIndex:400}} onClick={()=>setFamilyOpen(false)}/><div style={{position:"fixed",top:"50%",left:"50%",transform:"translate(-50%,-50%)",background:"linear-gradient(180deg,#2d1206,#180900)",border:"2px solid #92400e",borderRadius:12,padding:"20px",zIndex:401,width:"min(90vw,360px)"}}>
        <div style={{display:"flex",justifyContent:"space-between",marginBottom:14}}><h3 style={{margin:0,color:"#fbbf24",fontSize:15}}>設定</h3><button onClick={()=>setFamilyOpen(false)} style={{background:"none",border:"none",color:"#92400e",fontSize:20,cursor:"pointer"}}>✕</button></div>
        <div style={{display:"flex",gap:12,alignItems:"center",marginBottom:14}}>
          <div style={{width:70,height:70,border:"1px solid #78350f",borderRadius:6,background:"#0f0601",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,overflow:"hidden"}}>{familyCrest?<img src={familyCrest} style={{width:"100%",height:"100%",objectFit:"contain"}}/>:<span style={{fontSize:30,opacity:.3}}>⚜️</span>}</div>
          <div style={{display:"flex",flexDirection:"column",gap:6}}>
            <button onClick={()=>crestRef.current?.click()} style={{background:"#3b1a08",color:"#fbbf24",border:"1px solid #92400e",padding:"7px 12px",borderRadius:5,cursor:"pointer",fontSize:12}}>⚜ 家紋をアップロード</button>
            {familyCrest&&<button onClick={()=>setFamilyCrest(null)} style={{background:"none",color:"#ef4444",border:"1px solid #7f1d1d",padding:"5px 12px",borderRadius:5,cursor:"pointer",fontSize:12}}>削除</button>}
            <input ref={crestRef} type="file" accept="image/*" style={{display:"none"}} onChange={hCrest}/>
          </div>
        </div>
        <label style={{color:"#a16207",fontSize:10,display:"block",marginBottom:4}}>家訓</label>
        <input value={familyMotto} onChange={e=>setFamilyMotto(e.target.value)} style={{...IS,marginBottom:14}} placeholder="例：Toujours Pur"/>
        <label style={{color:"#fbbf24",fontSize:11,display:"block",marginBottom:2,fontWeight:"700"}}>★ 家系図タイトル（画像上部に大きく表示）</label>
        <p style={{color:"#d1a054",fontSize:10,margin:"0 0 6px"}}>PNG保存・HTML保存時に家系図の上部中央に表示されます</p>
        <input value={familyTitle} onChange={e=>setFamilyTitle(e.target.value)} style={{...IS,marginBottom:4}} placeholder="例：The Coopers"/>
        <button onClick={()=>setFamilyOpen(false)} style={{width:"100%",marginTop:14,background:"#92400e",color:"#fef3c7",border:"none",padding:"11px",borderRadius:6,cursor:"pointer",fontSize:14,fontWeight:"700"}}>保存</button>
      </div></>)}
      {bulkOpen&&(<><div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.6)",zIndex:400}} onClick={()=>setBulkOpen(false)}/><div style={{position:"fixed",top:"50%",left:"50%",transform:"translate(-50%,-50%)",background:"#2d1206",border:"2px solid #92400e",borderRadius:12,padding:"20px",zIndex:401,width:"min(90vw,400px)"}}><h3 style={{margin:"0 0 10px",color:"#fbbf24",fontSize:14}}>テキストで一括入力</h3><p style={{color:"#d1a054",fontSize:11,margin:"0 0 10px"}}>1行1キャラ。カンマ区切り：名前, フリガナ, 生年, 没年</p><textarea value={bulkText} onChange={e=>setBulkText(e.target.value)} style={{...IS,height:110,resize:"vertical"}} placeholder={"藤堂ミラ, Milla Tohdoh, 1978,\nフレッド・ウィーズリー, Fred Weasley, 1978, 1998"}/><div style={{display:"flex",gap:8,marginTop:12}}><button onClick={doBulk} style={{flex:1,background:"#92400e",color:"#fef3c7",border:"none",padding:"10px",borderRadius:6,cursor:"pointer",fontSize:13}}>追加</button><button onClick={()=>setBulkOpen(false)} style={{background:"none",color:"#92400e",border:"1px solid #92400e",padding:"10px 16px",borderRadius:6,cursor:"pointer",fontSize:13}}>キャンセル</button></div></div></>)}
      {helpOpen&&(<><div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.6)",zIndex:400}} onClick={()=>setHelpOpen(false)}/><div style={{position:"fixed",top:"50%",left:"50%",transform:"translate(-50%,-50%)",background:"linear-gradient(180deg,#2d1206,#180900)",border:"2px solid #92400e",borderRadius:12,padding:"20px",zIndex:401,width:"min(90vw,380px)",maxHeight:"80dvh",overflowY:"auto"}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:12}}><h3 style={{margin:0,color:"#fbbf24",fontSize:15}}>使い方</h3><button onClick={()=>setHelpOpen(false)} style={{background:"none",border:"none",color:"#92400e",fontSize:20,cursor:"pointer"}}>✕</button></div>{[["ノードをタップ","キャラクターの編集パネルを開きます。"],["ノードをドラッグ","ノードを移動します。"],["⟷を押す","接続モードに入ります。"],["接続モード：別ノードをタップ","直接線で繋げます。"],["接続モード：線をタップ","●（婚姻点）を作成して繋げます。"],["●の⟷→別ノードをタップ","●から子ノードへ繋げます。"],["線をタップ","選択→ 🗑 で削除。"],["ピンチ / ホイール","ズームイン・アウト。"]].map(([t,d])=>(<div key={t} style={{marginBottom:12}}><div style={{color:"#fbbf24",fontSize:12,fontWeight:"700",marginBottom:3}}>▸ {t}</div><div style={{color:"#d1a054",fontSize:11}}>{d}</div></div>))}</div></>)}
      
      {adjustMode&&(()=>{
        const ac=chars.find(c=>c.id===adjustTargetId);
        if(!ac)return null;
        const isImg=adjustMode==='img';
        const sliders=isImg
          ?[["左右","imgX",-30,30,1],["上下","imgY",-30,30,1],["サイズ","imgScale",0.5,2,0.05]]
          :[["左右","burnX",-40,40,1],["上下","burnY",-40,40,1],["サイズ","burnScale",0.3,2.5,0.05]];
        return(
          <div onPointerDown={e=>e.stopPropagation()} onPointerMove={e=>e.stopPropagation()} style={{position:"fixed",top:60,right:12,width:220,background:"linear-gradient(180deg,#2d1206,#180900)",border:`2px solid ${isImg?"#92400e":"#7f1d1d"}`,borderRadius:12,padding:"12px 14px",zIndex:500,boxShadow:"0 4px 24px rgba(0,0,0,.7)"}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
              <span style={{color:isImg?"#fbbf24":"#ef4444",fontSize:12,fontWeight:700}}>{isImg?"📷 顔写真の調整":"🔥 焼け跡の調整"}</span>
              <div style={{display:"flex",gap:6}}>
                <button onClick={()=>{setEditId(adjustTargetId);setAdjustMode(null);}}
                  style={{background:"#3b1a08",border:"1px solid #92400e",color:"#fbbf24",fontSize:10,padding:"3px 8px",borderRadius:4,cursor:"pointer"}}>編集に戻る</button>
                <button onClick={()=>setAdjustMode(null)}
                  style={{background:"none",border:"none",color:"#92400e",fontSize:16,cursor:"pointer",padding:0}}>✕</button>
              </div>
            </div>
            {sliders.map(([lb,k,mn,mx,st])=>{
              const val=ac[k]!==undefined?ac[k]:(k==="imgScale"?1:k==="burnScale"?0.45:k==="burnY"?-7:0);
              return(
                <div key={k} style={{marginBottom:8}}>
                  <div style={{display:"flex",justifyContent:"space-between",marginBottom:2}}>
                    <span style={{color:"#a16207",fontSize:10}}>{lb}</span>
                    <div style={{display:"flex",gap:4,alignItems:"center"}}>
                      <span style={{color:"#78716c",fontSize:10,minWidth:28,textAlign:"right"}}>{val.toFixed(2)}</span>
                      <button onClick={()=>{const dv=k==="imgScale"||k==="burnScale"?1:0;setChars(p=>p.map(c=>c.id===ac.id?{...c,[k]:dv}:c));}}
                        style={{background:"none",border:"none",color:"#555",fontSize:10,cursor:"pointer",padding:0}}>↺</button>
                    </div>
                  </div>
                  <input type="range" min={mn} max={mx} step={st} value={val}
                    onChange={e=>{const v=parseFloat(e.target.value);setChars(p=>p.map(c=>c.id===ac.id?{...c,[k]:v}:c));}}
                    onTouchStart={e=>e.stopPropagation()}
                    onTouchMove={e=>{e.stopPropagation();const r=e.currentTarget;const t=e.touches[0];const rect=r.getBoundingClientRect();const ratio=Math.min(1,Math.max(0,(t.clientX-rect.left)/rect.width));const v=parseFloat((mn+ratio*(mx-mn)).toFixed(2));setChars(p=>p.map(c=>c.id===ac.id?{...c,[k]:v}:c));}}
                    style={{width:"100%",accentColor:isImg?"#d97706":"#dc2626",touchAction:"auto"}}/>
                </div>
              );
            })}
          </div>
        );
      })()}
      {editId&&ed&&(<><div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.55)",zIndex:200}} onClick={()=>{const isEmpty=!ed.name&&!ed.kana&&!ed.birth&&!ed.death&&!ed.desc&&!ed.img;if(isEmpty)delChar(ed.id);setEditId(null);}}/><div style={{position:"fixed",bottom:0,left:0,right:0,maxHeight:"82dvh",display:"flex",flexDirection:"column",background:"linear-gradient(180deg,#2d1206,#180900)",borderTop:"2px solid #92400e",borderRadius:"16px 16px 0 0",zIndex:201}}><div style={{overflowY:"auto",flex:1,padding:"14px 16px 8px"}}>
        <div style={{width:36,height:4,background:"#78350f",borderRadius:2,margin:"0 auto 12px"}}/>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}><h2 style={{margin:0,color:"#fbbf24",fontSize:15}}>キャラクター編集</h2><button onClick={()=>{const isEmpty=!ed.name&&!ed.kana&&!ed.birth&&!ed.death&&!ed.desc&&!ed.img;if(isEmpty)delChar(ed.id);setEditId(null);}} style={{background:"none",border:"none",color:"#92400e",fontSize:20,cursor:"pointer"}}>✕</button></div>
        <div style={{display:"flex",gap:14,alignItems:"center",marginBottom:14}}>
          <div style={{position:"relative",width:90,height:90,flexShrink:0}}>
            <div style={{position:"absolute",left:"50%",top:"50%",transform:"translate(-50%,-48%)",width:64,height:76,borderRadius:"50%",overflow:"hidden",background:"#1a0800",filter:"none"}}>{ed.img?<img src={ed.img} style={{width:"100%",height:"100%",objectFit:"cover"}}/>:<div style={{width:"100%",height:"100%",display:"flex",alignItems:"center",justifyContent:"center",fontSize:28,color:"#555"}}>👤</div>}</div>
            <img src={FRAME_SRC} style={{position:"absolute",inset:0,width:"100%",height:"100%",objectFit:"contain",pointerEvents:"none"}}/>
          </div>
          <div style={{display:"flex",flexDirection:"column",gap:6}}>
            <button onClick={()=>fileRef.current?.click()} style={{background:"#3b1a08",color:"#fbbf24",border:"1px solid #92400e",padding:"8px 12px",borderRadius:6,cursor:"pointer",fontSize:12}}>📷 顔写真アップロード</button>
            {ed.img&&<button onClick={()=>setEd(d=>({...d,img:null}))} style={{background:"none",color:"#ef4444",border:"1px solid #ef4444",padding:"6px 12px",borderRadius:6,cursor:"pointer",fontSize:12}}>写真を削除</button>}
            <input ref={fileRef} type="file" accept="image/*" style={{display:"none"}} onChange={hImg}/>
          </div>
        </div>
        {ed.img&&<button onClick={()=>{setAdjustTargetId(ed.id);setEditId(null);setAdjustMode('img');}}
          style={{width:"100%",background:"#3b1a08",color:"#fbbf24",border:"1px solid #92400e",padding:"8px",borderRadius:6,cursor:"pointer",fontSize:12,marginBottom:6,marginTop:4}}>
          📷 顔写真の位置・サイズを調整
        </button>}
        {ed.disinherited&&<>
          <div style={{display:"flex",gap:12,marginBottom:6,marginTop:4}}>
            {[["burn","🔥 焦げ跡"],["ink","🖋 インク"]].map(([v,lb])=>(
              <label key={v} style={{display:"flex",alignItems:"center",gap:4,color:v==="burn"?"#ef4444":"#a16207",fontSize:12,cursor:"pointer"}}>
                <input type="radio" name="disStyle" value={v}
                  checked={(ed.disStyle||"burn")===v}
                  onChange={()=>{setEd(d=>({...d,disStyle:v}));setChars(p=>p.map(c=>c.id===ed.id?{...c,disStyle:v}:c));}}
                  style={{accentColor:v==="burn"?"#dc2626":"#d97706"}}/>
                {lb}
              </label>
            ))}
          </div>
          <button onClick={()=>{setAdjustTargetId(ed.id);setEditId(null);setAdjustMode('burn');}}
            style={{width:"100%",background:"#3b1a08",color:"#ef4444",border:"1px solid #7f1d1d",padding:"8px",borderRadius:6,cursor:"pointer",fontSize:12,marginBottom:6}}>
            🔥 エフェクトの位置・サイズを調整
          </button>
        </>}
        <div style={{display:"flex",flexDirection:"column",gap:9}}>
          {[["名前","name","例：藤堂ミラ"],["フリガナ","kana","Milla Tohdoh"]].map(([lb,k,ph])=>(<div key={k}><label style={{color:"#a16207",fontSize:10,display:"block",marginBottom:3}}>{lb}</label><input value={ed[k]||""} onChange={e=>{const v=e.target.value;setEd(d=>({...d,[k]:v}));setChars(p=>p.map(c=>c.id===ed.id?{...c,[k]:v}:c));}} style={IS} placeholder={ph}/></div>))}
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
            <div><label style={{color:"#a16207",fontSize:10,display:"block",marginBottom:3}}>生年（西暦）</label><input value={ed.birth||""} onChange={e=>{const v=e.target.value;setEd(d=>({...d,birth:v}));setChars(p=>p.map(c=>c.id===ed.id?{...c,birth:v}:c));}} style={IS} placeholder="1978"/></div>
            <div><label style={{color:"#a16207",fontSize:10,display:"block",marginBottom:3}}>没年（故人のみ）</label><input value={ed.death||""} onChange={e=>{const v=e.target.value;setEd(d=>({...d,death:v}));setChars(p=>p.map(c=>c.id===ed.id?{...c,death:v}:c));}} style={IS} placeholder="1998"/></div>
          </div>
          <div><label style={{color:"#a16207",fontSize:10,display:"block",marginBottom:3}}>説明文 <span style={{opacity:.6}}>（HTML保存時のみホバーで表示）</span></label><textarea value={ed.desc||""} onChange={e=>{const v=e.target.value;setEd(d=>({...d,desc:v}));setChars(p=>p.map(c=>c.id===ed.id?{...c,desc:v}:c));}} style={{...IS,height:60,resize:"vertical"}} placeholder="杖・役職・メモなど"/></div>
        </div>
        <div style={{display:"flex",gap:16,marginTop:12,flexWrap:"wrap",alignItems:"center"}}>
          {[["故人","deceased","#d1a054"],["マグル","muggle","#d1a054"],["勘当","disinherited","#ef4444"]].map(([lb,k,col])=>(<label key={k} style={{display:"flex",alignItems:"center",gap:6,color:col,fontSize:13,cursor:"pointer"}}><input type="checkbox" checked={!!ed[k]} onChange={e=>{const v=e.target.checked;setEd(d=>({...d,[k]:v}));setChars(p=>p.map(c=>c.id===ed.id?{...c,[k]:v}:c));}} style={{accentColor:k==="disinherited"?"#dc2626":"#d97706",width:16,height:16}}/>{lb}</label>))}
          <button onClick={()=>{delChar(ed.id);setEditId(null);}} style={{marginLeft:"auto",background:"none",color:"#ef4444",border:"1px solid #ef4444",padding:"6px 12px",borderRadius:6,cursor:"pointer",fontSize:12}}>削除</button>
        </div>
        </div></div></>)}
    </div>
  );
}
export default App;
